import { Mesh, PlaneGeometry, BoxGeometry, Group, Color, DoubleSide, BackSide, FrontSide } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'journal-card-3';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Atlas region 512x320 -> aspect 1.6:1
  const cardW = 1.6;
  const cardH = 1.0;
  const cardDepth = 0.05;

  // ---- Card body (extruded box with image on front face) ----
  const boxGeo = new BoxGeometry(cardW, cardH, cardDepth);

  // Front face material carries the image (MeshBasic per render mode guidance)
  const frontMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 1,
    side: DoubleSide
  });

  // Side / back materials - machined metal feel picked up by scene key + ambient
  const sideMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
    transparent: true,
    opacity: 1
  });
  const backMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.4,
    roughness: 0.6,
    transparent: true,
    opacity: 1
  });

  // Material array: [ +x, -x, +y, -y, +z(front), -z(back) ]
  const boxMats = [sideMat, sideMat, sideMat, sideMat, frontMat, backMat];
  const cardMesh = new Mesh(boxGeo, boxMats);
  group.add(cardMesh);

  // Load image onto front face
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      frontMat.map = tex;
      frontMat.color = new Color(0xffffff);
      frontMat.needsUpdate = true;
    });
  }

  // ---- Accent edge strip (left vertical) ----
  const accentMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.0,
    side: DoubleSide
  });
  const accentGeo = new BoxGeometry(0.035, cardH + 0.004, cardDepth + 0.004);
  const accentEdge = new Mesh(accentGeo, accentMat);
  accentEdge.position.x = -cardW / 2 - 0.016;
  group.add(accentEdge);

  // ---- Thin paper-tinted border frame front ----
  const frameMat = new MeshBasicNodeMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 0.06,
    side: DoubleSide
  });
  const borderT = 0.01;
  // top / bottom / right (left is accent)
  const tbGeo = new BoxGeometry(cardW + 0.004, borderT, cardDepth + 0.004);
  const topF = new Mesh(tbGeo, frameMat);
  topF.position.set(0, cardH / 2 + borderT / 2, 0);
  group.add(topF);
  const botF = new Mesh(tbGeo, frameMat);
  botF.position.set(0, -cardH / 2 - borderT / 2, 0);
  group.add(botF);
  const sideGeo = new BoxGeometry(borderT, cardH + 0.004, cardDepth + 0.004);
  const rightF = new Mesh(sideGeo, frameMat);
  rightF.position.set(cardW / 2 + borderT / 2, 0, 0);
  group.add(rightF);

  // ---- Stock badge (inventory.status.inStock data binding) ----
  // Default render: "IN STOCK" with accent dot; binding request recorded via emit on select
  const badgeGroup = new Group();
  badgeGroup.position.set(-cardW / 2 + 0.16, -cardH / 2 + 0.09, cardDepth / 2 + 0.002);
  group.add(badgeGroup);

  // Accent dot
  const dotGeo = new THREE.CircleGeometry(0.022, 16);
  const dotMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.95
  });
  const dot = new Mesh(dotGeo, dotMat);
  dot.position.x = -0.0;
  badgeGroup.add(dot);

  const badgeLabel = ctx.fontAtlas.createText('IN STOCK', {
    fontSize: 18,
    color: colors.paper,
    align: 'left'
  });
  badgeLabel.position.x = 0.04;
  badgeLabel.scale.setScalar(0.0035);
  badgeGroup.add(badgeLabel);

  // ---- Bottom caption strip overlay (subtle gradient via a translucent accent line) ----
  const stripGeo = new PlaneGeometry(cardW, 0.22);
  const stripMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.55
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardH / 2 + 0.11, cardDepth / 2 + 0.001);
  group.add(strip);

  const stripLabel = ctx.fontAtlas.createText('JOURNAL // ENTRY 03', {
    fontSize: 14,
    color: colors.paper,
    align: 'left'
  });
  stripLabel.position.set(-cardW / 2 + 0.12, -0.015, 0.0011);
  stripLabel.scale.setScalar(0.0028);
  strip.add(stripLabel);

  // ---- Entrances (rise-in) ----
  const tl = gsap.timeline({ delay: 0.35 });
  tl.from(group.position, { y: '+=0.4', duration: 0.7, ease: 'power3.out' });
  tl.from(group.scale, { x: 0.94, y: 0.94, z: 0.94, duration: 0.7, ease: 'power3.out' }, '<');
  tl.from(frontMat, { opacity: 0, duration: 0.5, ease: 'power2.out' }, '<');
  tl.from(sideMat, { opacity: 0, duration: 0.5, ease: 'power2.out' }, '<');
  tl.from(backMat, { opacity: 0, duration: 0.5, ease: 'power2.out' }, '<');
  tl.to(accentMat, { opacity: 0.85, duration: 0.6, ease: 'power2.out' }, '-=0.1');

  // ---- Idle breathing ----
  const breathe = gsap.to(group.position, {
    y: '+=0.025',
    duration: 3.4,
    ease: 'sine.inOut',
    repeat: -1,
    yoyo: true,
    delay: 1.4
  });

  // ---- Interaction handlers ----
  const state = { focusScale: 1, hovering: false };
  let pressTimeline = null;

  group.userData.handlers = {
    pointerenter: () => {
      if (state.hovering) return;
      state.hovering = true;
      gsap.to(group.position, { z: 0.15, duration: 0.5, ease: 'power3.out' });
      gsap.to(accentMat, { opacity: 1.0, duration: 0.3, ease: 'power2.out' });
      gsap.to(group.scale, {
        x: 1.03, y: 1.03, z: 1.03,
        duration: 0.35, ease: 'power3.out', overwrite: 'auto'
      });
    },
    pointerleave: () => {
      if (!state.hovering) return;
      state.hovering = false;
      gsap.to(group.position, { z: 0, duration: 0.5, ease: 'power3.out' });
      gsap.to(accentMat, { opacity: 0.85, duration: 0.3, ease: 'power2.out' });
      gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.5, ease: 'power3.out', overwrite: 'auto'
      });
    },
    click: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline();
      pressTimeline
        .to(group.scale, {
          x: 0.97, y: 0.97, z: 0.97,
          duration: 0.12, ease: 'back.out(2)'
        })
        .to(group.scale, {
          x: state.hovering ? 1.03 : 1,
          y: state.hovering ? 1.03 : 1,
          z: state.hovering ? 1.03 : 1,
          duration: 0.3, ease: 'back.out(1.7)'
        });
      ctx.emit('hub-journal.select', { id: 'journal-card-3', source: 'trpc.inventory.status' });
    }
  };

  // Held reference to badge label so binding-driven updates are possible
  group.userData.stockBadge = badgeGroup;
  group.userData.setStockBadge = (inStock) => {
    if (inStock) {
      dotMat.color = new Color(colors.accent);
      badgeLabel.userData?.setText?.('IN STOCK');
    } else {
      dotMat.color = new Color(colors.paper);
      badgeLabel.userData?.setText?.('SOLD OUT');
    }
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    breathe.kill();
    if (pressTimeline) pressTimeline.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(frontMat);
    gsap.killTweensOf(sideMat);
    gsap.killTweensOf(backMat);
    gsap.killTweensOf(accentMat);
    boxGeo.dispose();
    accentGeo.dispose();
    tbGeo.dispose();
    sideGeo.dispose();
    stripGeo.dispose();
    dotGeo.dispose();
    frontMat.dispose();
    sideMat.dispose();
    backMat.dispose();
    accentMat.dispose();
    frameMat.dispose();
    stripMat.dispose();
    dotMat.dispose();
  };

  return group;
}
